from fastapi import FastAPI, Body
from pydantic import BaseModel, ConfigDict
from fastapi.testclient import TestClient
from typing import Any

class CustomType:
    def __init__(self, value):
        self.value = value
    def __repr__(self):
        return f"CustomType({self.value})"

app = FastAPI()

@app.post("/test")
async def test_endpoint(
    name: str = Body(),
    custom: Any = Body()
):
    return {"name": name, "custom": custom}

# We need to force Pydantic to validate 'custom' as CustomType.
# But since we used Any, it won't fail.
# Let's use CustomType as the annotation.

app = FastAPI()

@app.post("/test")
async def test_endpoint(
    name: str = Body(),
    custom: CustomType = Body()
):
    return {"name": name, "custom": custom}

client = TestClient(app)

try:
    response = client.post("/test", json={"name": "test", "custom": "some value"})
    print(f"Response: {response.status_code}, {response.json()}")
except Exception as e:
    print(f"Error: {e}")
